resources.description:
Sample IAM policies for least privilege access to Amazon Elastic Compute Cloud (EC2)


*Read Only Policy:*

[source,json,subs="verbatim,attributes"]
----
{
  "Version": "2012-10-17",{tcx5-2025-waiver}
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "ec2:Describe*",
        "ec2:List*",
        "ec2:Get*"
      ],
      "Resource": "*"
    }
  ]
}
----


*Operator Policy:*

[source,json,subs="verbatim,attributes"]
----
{
  "Version": "2012-10-17",{tcx5-2025-waiver}
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "ec2:Describe*",
        "ec2:List*",
        "ec2:Get*",
        "ec2:StartInstances",
        "ec2:StopInstances",
        "ec2:RebootInstances"
      ],
      "Resource": "*",
      "Condition": {
        "Bool": {
          "aws:MultiFactorAuthPresent": "true"
        }
      }
    }
  ]
}
----


*Administrator Policy:*

[source,json,subs="verbatim,attributes"]
----
{
  "Version": "2012-10-17",{tcx5-2025-waiver}
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "ec2:*",
      "Resource": "*",
      "Condition": {
        "Bool": {
          "aws:MultiFactorAuthPresent": "true"
        },
        "NumericLessThan": {
          "aws:MultiFactorAuthAge": "3600"
        }
      }
    }
  ]
}
----
